var e={topic:`faith-spiritual-life`,lang:`ar`,strings:[{t:`تصف Charlotte Christian نفسها بأنها «مدرسة محورها المسيح تُعِدّ للجامعة». وهي مستقلة ولا تتبع طائفة بعينها. يدرس كل طالب مادة الكتاب المقدّس كل سنة، من Junior Kindergarten حتى الصف 12. ولكل قسم اجتماع روحي أسبوعي.`,of:`e78f96fc`,at:[`charlotte-christian:lead.strong`]},{t:`تقول المدرسة: «المدرسة ليست تحت إدارة أي كنيسة بعينها ولا نفوذها ولا دعمها».`,of:`3b304585`,at:[`charlotte-christian:lead.muted`]},{t:`أسبوعيًّا`,of:`417cc4ce`,at:[`charlotte-christian:stats[0].value`]},{t:`اجتماع روحي في كل قسم`,of:`bd8a9141`,at:[`charlotte-christian:stats[0].label`]},{t:`Lower School أيام الخميس، وMiddle School أيام الثلاثاء، وUpper School أيام الأربعاء، بحسب تقويم 2026–27`,of:`fe7bc3fd`,at:[`charlotte-christian:stats[0].note`]},{t:`أرصدة في الدراسات الكتابية للتخرّج`,of:`0c43c16a`,at:[`charlotte-christian:stats[1].label`]},{t:`مادة واحدة في الكتاب المقدّس عن كل سنة يكون الطالب مسجّلًا فيها في Upper School`,of:`fbf979d1`,at:[`charlotte-christian:stats[1].note`]},{t:`كنيسة مسيحية، وأكثر`,of:`1033fce9`,at:[`charlotte-christian:stats[2].label`]},{t:`«أسرنا أعضاء في أكثر من 130 كنيسة مسيحية مختلفة»`,of:`71766cd1`,at:[`charlotte-christian:stats[2].note`]},{t:`ساعة خدمة، دفعة 2026`,of:`dd23d2b8`,at:[`charlotte-christian:stats[3].label`]},{t:`أنجزتها الدفعة خلال سنواتها في Upper School`,of:`d858a35b`,at:[`charlotte-christian:stats[3].note`]},{t:`لكل قسم اجتماعه الروحي الأسبوعي في قاعة المدرسة، وتجتمع المدرسة كلها في أربعة اجتماعات أخرى في السنة. ويتلقّى أولياء الأمور بالبريد الإلكتروني ملخّصًا لاجتماعات كل أسبوع.`,of:`b6b4524b`,at:[`charlotte-christian:chapel.headline`]},{t:`الاجتماع الروحي في Lower School`,of:`00c05305`,at:[`charlotte-christian:chapel.entries[0].title`]},{t:`أيام الخميس، 8:15–8:45 صباحًا، في Alkire Auditorium. «اجتماعات روحية أسبوعية يقودها مدير الحياة الروحية».`,of:`9578beba`,at:[`charlotte-christian:chapel.entries[0].text`]},{t:`من المتحدثين المذكورين لخريف 2026 مرشد/ة Lower School ومدير/ة Lower School. وفي أحد الأسابيع، مثّل المعلّمون والطلاب قصة من سفر دانيال.`,of:`ce1d7c82`,at:[`charlotte-christian:chapel.entries[0].muted`]},{t:`الاجتماع الروحي في Middle School`,of:`16378e57`,at:[`charlotte-christian:chapel.entries[1].title`]},{t:`أيام الثلاثاء، 9:30–10:05 صباحًا، في Alkire Auditorium. تُقدَّم الاجتماعات في سلاسل بأسماء مثل «Blessing Burglars» (لصوص البركات).`,of:`a497ab45`,at:[`charlotte-christian:chapel.entries[1].text`]},{t:`من المتحدثين المذكورين لعام 2026 راعي الحرم المدرسي، ومدير/ة الحياة الروحية في Middle School، ومعلّمون من Middle School، وأحد القادة الطلاب في Upper School. ويزور المدرسة قادة عبادة ضيوف.`,of:`d9ed8570`,at:[`charlotte-christian:chapel.entries[1].muted`]},{t:`الاجتماع الروحي في Upper School`,of:`c9d9a258`,at:[`charlotte-christian:chapel.entries[2].title`]},{t:`أيام الأربعاء، 9:25–10:05 صباحًا، في Alkire Auditorium.`,of:`37fdadb0`,at:[`charlotte-christian:chapel.entries[2].text`]},{t:`من الاجتماعات الأخيرة كلمة لمدير/ة Upper School و«حلقة نقاش لأسر من Charlotte Christian» عن «معنى أن نكرم الله كأسرة».`,of:`798e1179`,at:[`charlotte-christian:chapel.entries[2].muted`]},{t:`اجتماعات روحية للمدرسة كلها`,of:`e2630cbf`,at:[`charlotte-christian:chapel.entries[3].title`,`hickory-grove-christian:chapel.entries[2].title`]},{t:`أربعة في تقويم 2026–27: العودة إلى المدرسة، وعيد الشكر، وعيد القيامة، واليوم الوطني للصلاة، وتُقام في الهواء الطلق في ملعب المدرسة وفي مدرّجها.`,of:`fc758c66`,at:[`charlotte-christian:chapel.entries[3].text`]},{t:`ولطلاب السنة الأخيرة أيضًا خدمة عبادة للتخرّج (Baccalaureate Service) في مايو.`,of:`ea028f36`,at:[`charlotte-christian:chapel.entries[3].muted`]},{t:`KnightLight Worship`,of:`38ca8c7e`,at:[`charlotte-christian:chapel.entries[4].title`]},{t:`فريق العبادة في Lower School. «يحقّ لطلاب الصفين 3 و4 التقدّم لتجربة الأداء». يتدرّب الفريق أيام الأربعاء بعد المدرسة ويقود «العبادة في الاجتماع الروحي لـLower School عدة مرات هذا الفصل الدراسي».`,of:`800f648f`,at:[`charlotte-christian:chapel.entries[4].text`]},{t:`uKnight Worship`,of:`a9fb8cb7`,at:[`charlotte-christian:chapel.entries[5].title`]},{t:`فريق عبادة طلابي من «مرنّمين وعازفين وطلاب فنّيين في الصفوف 9-12 يقودون العبادة في الاجتماعات الروحية على مدار السنة». وهو مقرّر بمستوى Honors يُلتحق به بتجربة أداء، وقيمته نصف رصيد، ويمكن أن يُحتسب ضمن متطلّب الفنون الجميلة.`,of:`164eb926`,at:[`charlotte-christian:chapel.entries[5].text`]},{t:`أولياء الأمور يعرفون ما عُلِّم.`,of:`30cb3d72`,at:[`charlotte-christian:chapel.note.strong`]},{t:`يرسل مديرو الحياة الروحية الثلاثة كل أسبوع بريدًا إلكترونيًّا باسم Chapel Recap (ملخّص الاجتماع الروحي)، ومعه قائمة تشغيل لـ«الترانيم التي رنّمناها في الاجتماع الروحي هذا الأسبوع».`,of:`e6d128ad`,at:[`charlotte-christian:chapel.note.text`]},{t:`ينتهي كل اجتماع روحي بالبركة الختامية نفسها، من Micah 6:8. وتتبع أيام الاجتماعات ومواعيدها تقويم المدرسة لعام 2026–27. وبعض الأسابيع بلا اجتماع روحي.`,of:`898d5f14`,at:[`charlotte-christian:chapel.note.muted`]},{t:`الكتاب المقدّس مادة مطلوبة كل سنة من Junior Kindergarten حتى الصف 12. إليك ما يدرسه كل صف، والأرصدة الأربعة التي يحتاجها طالب Upper School للتخرّج.`,of:`2ac4ec61`,at:[`charlotte-christian:classes.headline`]},{t:`«دراسة الكتاب المقدّس جزء مطلوب من المنهج، يبدأ في Junior Kindergarten ويستمر حتى الصف 12».`,of:`a011b44b`,at:[`charlotte-christian:classes.intro.text`]},{t:`«تُستخدم ترجمة English Standard Version للكتاب المقدّس في جميع الصفوف». تشتري الأسر الكتاب المقدّس؛ وهو مدرج في قوائم المستلزمات المدرسية للصفوف 1–12.`,of:`ca8c90ba`,at:[`charlotte-christian:classes.intro.muted`]},{t:`Lower School`,of:`0921a0ca`,at:[`charlotte-christian:classes.groups[0].name`]},{t:`دروس يومية في الكتاب المقدّس`,of:`733a59bd`,at:[`charlotte-christian:classes.groups[0].tally`]},{t:`Junior Kindergarten`,of:`5ee6535c`,at:[`charlotte-christian:classes.groups[0].rows[0].label`]},{t:`«أبطال الإيمان، محبة الله للجميع، حقّ كلمة الله»`,of:`b20811bb`,at:[`charlotte-christian:classes.groups[0].rows[0].detail`]},{t:`Kindergarten`,of:`68541d89`,at:[`charlotte-christian:classes.groups[0].rows[1].label`]},{t:`«نظرة عامة على الكتاب المقدّس»`,of:`3ee57c76`,at:[`charlotte-christian:classes.groups[0].rows[1].detail`]},{t:`الصف 1`,of:`20673dd7`,at:[`charlotte-christian:classes.groups[0].rows[2].label`]},{t:`«من الخليقة إلى أرض الموعد»`,of:`54566fbf`,at:[`charlotte-christian:classes.groups[0].rows[2].detail`]},{t:`الصف 2`,of:`21673f6a`,at:[`charlotte-christian:classes.groups[0].rows[3].label`]},{t:`«الأناجيل»`,of:`105465d2`,at:[`charlotte-christian:classes.groups[0].rows[3].detail`]},{t:`الصف 3`,of:`226740fd`,at:[`charlotte-christian:classes.groups[0].rows[4].label`]},{t:`«إسرائيل»`,of:`53429d22`,at:[`charlotte-christian:classes.groups[0].rows[4].detail`]},{t:`الصف 4`,of:`1b6735f8`,at:[`charlotte-christian:classes.groups[0].rows[5].label`]},{t:`«أعمال الرسل والكنيسة الأولى». ويدرس طلاب الصف الرابع أيضًا «مقرّرًا تمهيديًّا في الدفاعيات المسيحية» (أي تعلُّم شرح الإيمان والدفاع عنه).`,of:`5497d699`,at:[`charlotte-christian:classes.groups[0].rows[5].detail`]},{t:`Middle School`,of:`15441234`,at:[`charlotte-christian:classes.groups[1].name`,`hickory-grove-christian:classes.groups[1].name`]},{t:`مادة في الكتاب المقدّس كل سنة، مع قراءة يومية من الكتاب المقدّس`,of:`4b6fc13e`,at:[`charlotte-christian:classes.groups[1].tally`]},{t:`Bible 5`,of:`672446e6`,at:[`charlotte-christian:classes.groups[1].rows[0].label`]},{t:`النبوّة عن المسيح: «دراسة لسفر التكوين»`,of:`67866b7d`,at:[`charlotte-christian:classes.groups[1].rows[0].detail`]},{t:`Bible 6`,of:`66244553`,at:[`charlotte-christian:classes.groups[1].rows[1].label`]},{t:`الإعداد للمسيح: «دراسة للعهد القديم، تبدأ بسفر الخروج وتنتهي بـ400 سنة من الصمت».`,of:`72467c36`,at:[`charlotte-christian:classes.groups[1].rows[1].detail`]},{t:`Bible 7`,of:`652443c0`,at:[`charlotte-christian:classes.groups[1].rows[2].label`]},{t:`خطة المسيح: «نظرة عامة على العهد الجديد».`,of:`6acb1671`,at:[`charlotte-christian:classes.groups[1].rows[2].detail`]},{t:`Bible 8`,of:`74245b5d`,at:[`charlotte-christian:classes.groups[1].rows[3].label`]},{t:`شخص المسيح: حياة يسوع وتعليمه «كما يقدّمهما إنجيل يوحنا على نحو فريد».`,of:`29554636`,at:[`charlotte-christian:classes.groups[1].rows[3].detail`]},{t:`Upper School`,of:`bfabeb69`,at:[`charlotte-christian:classes.groups[2].name`]},{t:`4 أرصدة في الدراسات الكتابية للتخرّج`,of:`c9c95bce`,at:[`charlotte-christian:classes.groups[2].tally`]},{t:`Old Testament Survey`,of:`6b2cd411`,at:[`charlotte-christian:classes.groups[2].rows[0].label`,`hickory-grove-christian:classes.groups[2].rows[0].label`]},{t:`متطلّب السنة الأولى.`,of:`389bafe0`,at:[`charlotte-christian:classes.groups[2].rows[0].detail`]},{t:`New Testament Survey`,of:`15a0fcf0`,at:[`charlotte-christian:classes.groups[2].rows[1].label`,`hickory-grove-christian:classes.groups[2].rows[1].label`]},{t:`متطلّب السنة الثانية.`,of:`b9ac76f8`,at:[`charlotte-christian:classes.groups[2].rows[1].detail`]},{t:`Christian Theology`,of:`3a8071fd`,at:[`charlotte-christian:classes.groups[2].rows[2].label`]},{t:`متطلّب السنة الثالثة. «سيتعلّم الطلاب تاريخ الكنيسة من عصر العهد الجديد حتى الإصلاح».`,of:`5056d764`,at:[`charlotte-christian:classes.groups[2].rows[2].detail`]},{t:`World Religions`,of:`a0cf6333`,at:[`charlotte-christian:classes.groups[2].rows[3].label`]},{t:`متطلّب السنة الثالثة. المقرّر «دراسة نقدية للديانات القديمة، والديانات الشرقية (ومنها الهندوسية والبوذية)، واليهودية والإسلام».`,of:`ff42b6fe`,at:[`charlotte-christian:classes.groups[2].rows[3].detail`]},{t:`Apologetics and Cultural Engagement`,of:`6b124f9d`,at:[`charlotte-christian:classes.groups[2].rows[4].label`]},{t:`متطلّب السنة الأخيرة. يتناول الفصل الدراسي الأول الدفاعيات. ويتناول الثاني «الأسس الكتابية واللاهوتية للتفاعل مع الثقافة».`,of:`05c1557f`,at:[`charlotte-christian:classes.groups[2].rows[4].detail`]},{t:`الطالب الذي يلتحق متأخرًا يدرس الكتاب المقدّس أيضًا.`,of:`567deb60`,at:[`charlotte-christian:classes.note.strong`]},{t:`«يجب على الطلاب إتمام مادة في الكتاب المقدّس عن كل سنة يكونون مسجّلين فيها في Charlotte Christian School. وإذا قُبل طالب في السنة الأخيرة، فسيُطلب منه إتمام مادتَي الكتاب المقدّس للسنة الثالثة والسنة الأخيرة كلتيهما».`,of:`91bce979`,at:[`charlotte-christian:classes.note.text`]},{t:`يمكن للطلاب أيضًا التخرّج بتميّز في الكتاب المقدّس والفلسفة والدين. ومن شروطه معدّل GPA قدره 3.89 في مواد الكتاب المقدّس، ومشاركة فاعلة في كنيسة محلية، ومقابلة مع قسم الكتاب المقدّس.`,of:`2ce95422`,at:[`charlotte-christian:classes.note.muted`]},{t:`لكل قسم فعالية في الخريف مخصّصة للإيمان والصداقة. تسافر الصفوف 5–12 إلى جبال ولاية كارولاينا الشمالية، والتكلفة جزء من الرسوم الدراسية.`,of:`beed9505`,at:[`charlotte-christian:retreats.headline`]},{t:`Lower School: Camp S.L.A.M.`,of:`99a07ae0`,at:[`charlotte-christian:retreats.cells[0].title`]},{t:`«سيشارك جميع طلاب Lower School في يوم كامل من أنشطة Camp S.L.A.M. (Spiritual Life and Meaning، أي الحياة الروحية والمعنى)». يتضمّن اليوم ألعابًا جماعية و«التسبيح والعبادة والدراسة». وكان المتحدث في خريف 2026 مدير/ة الحياة الروحية في Lower School. وللصف 4 يوم خاص به للقيادة وبناء الفريق.`,of:`d5744e60`,at:[`charlotte-christian:retreats.cells[0].text`]},{t:`Middle School: Carolina Point`,of:`f2a7a675`,at:[`charlotte-christian:retreats.cells[1].title`]},{t:`«يشارك جميع الطلاب في خلوة Carolina Point السنوية، بوصفها جزءًا حيويًّا من تجربة Middle School»، وتُقام في مركز خلوات تابع لـYoung Life «خارج Brevard, N.C.». وكان موضوع خريف 2026 «The Rejoice Choice» (اختيار الفرح). في كل جلسة ألعاب وموسيقى عبادة ومتحدث، مع تأمّلات روحية في الأكواخ ليلًا.`,of:`1f0cbfe9`,at:[`charlotte-christian:retreats.cells[1].text`]},{t:`Upper School: Windy Gap`,of:`fd6412c8`,at:[`charlotte-christian:retreats.cells[2].title`]},{t:`تقول المدرسة: «يُطلب من جميع الطلاب المشاركة في خلوة Windy Gap السنوية»، وتُقام في مركز خلوات تابع لـYoung Life «خارج Asheville, N.C.». وكان موضوع خريف 2026 «Transformed by Christ» (متغيّرون بالمسيح). تُعقد أربع جلسات عبادة، ويلي كلًّا منها «Cabin Time, Reflection, and Sharing» (وقت في الأكواخ وتأمّل ومشاركة). ويذهب طلاب السنة الأخيرة قبل الآخرين بيوم.`,of:`0b4405fb`,at:[`charlotte-christian:retreats.cells[2].text`]},{t:`مشمول في الرسوم الدراسية:`,of:`adfa710e`,at:[`charlotte-christian:retreats.note.strong`]},{t:`«خلوتا Carolina Point وWindy Gap (خلوة الحياة الروحية لـMiddle School وUpper School ومدتها يومان) والرحلات الميدانية».`,of:`e5d1ff85`,at:[`charlotte-christian:retreats.note.text`]},{t:`«هذه الخلوات غير ممكنة إلا بدعم المتطوعين من أولياء الأمور».`,of:`ea0f66e6`,at:[`charlotte-christian:retreats.note.muted`]},{t:`حيث يتحدث الطلاب عن الإيمان في مجموعات أصغر: مجموعات قبل بدء الدوام، وتأمّلات روحية وقت الغداء، ومجموعات الإرشاد، والقادة الطلاب.`,of:`49db66b0`,at:[`charlotte-christian:groups.headline`]},{t:`مجموعات DIG (Discipleship In Groups، أي التلمذة في مجموعات)`,of:`e8091e48`,at:[`charlotte-christian:groups.entries[0].title`]},{t:`المجموعات «تجتمع قبل بدء الدوام صباح كل أربعاء من 7:10-7:35 صباحًا» في جزء من كل فصل دراسي. «سيقود هذه المجموعات طلاب متطوعون من Upper School بمساعدة أعضاء من هيئة التدريس في Middle School».`,of:`adce9425`,at:[`charlotte-christian:groups.entries[0].text`]},{t:`الغداء والتأمّلات الروحية`,of:`88ba61b5`,at:[`charlotte-christian:groups.entries[1].title`]},{t:`يقود/تقود مدير/ة الحياة الروحية في Middle School نقاشًا أسبوعيًّا وقت الغداء لبنين الصف 8. ومن المجموعات الأخرى «Dodgeball & Devotions» (كرة المراوغة والتأمّلات الروحية) لبنين الصفوف 5–7، ومجموعة تأمّلات روحية للبنات.`,of:`765d22c7`,at:[`charlotte-christian:groups.entries[1].text`]},{t:`الممالك ومجموعات الإرشاد`,of:`e9e85801`,at:[`charlotte-christian:groups.entries[2].title`]},{t:`«Six kingdoms, one king» (ست ممالك وملك واحد). ينضم كل طالب في Middle School إلى واحدة من ست مجموعات «تجتمع بانتظام على مدار السنة». وتعقد مجموعات الإرشاد دراسات في الكتاب المقدّس، ويمكن لطلاب الصف الثامن أن يخدموا في Kingdom Council (مجلس الممالك) من أجل «الحياة الروحية والحياة الطلابية».`,of:`aaa1b13a`,at:[`charlotte-christian:groups.entries[2].text`]},{t:`دراسات الكتاب المقدّس في Upper School`,of:`a456d99e`,at:[`charlotte-christian:groups.entries[3].title`]},{t:`يمكن لأولياء الأمور والمعلّمين أن يقودوا «دراسة في الكتاب المقدّس لطلاب Upper School» عن طريق مدير/ة الحياة الروحية في Upper School.`,of:`7bcf1ba1`,at:[`charlotte-christian:groups.entries[3].text`]},{t:`لا تذكر صفحات المدرسة متى تجتمع هذه المجموعات.`,of:`c5b18629`,at:[`charlotte-christian:groups.entries[3].muted`]},{t:`القادة الطلاب`,of:`e60ca716`,at:[`charlotte-christian:groups.entries[4].title`]},{t:`Spiritual Life Prefect (عريف الحياة الروحية) هو واحد من تسعة قادة طلاب في السنة الأخيرة. يتحدث العرفاء ويصلّون في الاجتماع الروحي، ويقود متطوعون من Upper School مجموعات DIG في Middle School.`,of:`bcb5af25`,at:[`charlotte-christian:groups.entries[4].text`]},{t:`مؤتمر الحياة الروحية`,of:`0a7d311a`,at:[`charlotte-christian:groups.entries[5].title`]},{t:`في أيام المؤتمر، «يُدعى متحدثون خاصون إلى الحرم المدرسي لوقت من التعليم والنقاش المركَّزين».`,of:`265c7d69`,at:[`charlotte-christian:groups.entries[5].text`]},{t:`رسالة المدرسة، وقيمها الأساسية الخمس، وبيان إيمانها المؤلَّف من عشرة بنود، بكلمات المدرسة نفسها.`,of:`ef08810f`,at:[`charlotte-christian:beliefs.headline`]},{t:`«Charlotte Christian School مدرسة محورها المسيح تُعِدّ للجامعة، تجهّز الطلاب وتنمّيهم ليدمجوا بفاعلية الحق الكتابي والتعلّم في حياتهم اليومية وليؤثّروا في الثقافة من أجل المسيح».`,of:`aed901a1`,at:[`charlotte-christian:beliefs.mission`]},{t:`أحبِب الله`,of:`aefdea87`,at:[`charlotte-christian:beliefs.values[0].name`]},{t:`أظهِر اللطف`,of:`6dca795d`,at:[`charlotte-christian:beliefs.values[1].name`]},{t:`اسلك بتواضع`,of:`0d4f9943`,at:[`charlotte-christian:beliefs.values[2].name`]},{t:`اسعَ إلى التميّز`,of:`93d0e213`,at:[`charlotte-christian:beliefs.values[3].name`]},{t:`اطلب الحق`,of:`635804ac`,at:[`charlotte-christian:beliefs.values[4].name`]},{t:`لا تدير المدرسةَ كنيسةٌ واحدة.`,of:`4eed29f4`,at:[`charlotte-christian:beliefs.note.strong`]},{t:`«يمثّل أعضاء مجلس الأمناء وهيئة التدريس والطلاب طوائف وممارسات متنوعة. والمدرسة ليست تحت إدارة أي كنيسة بعينها ولا نفوذها ولا دعمها».`,of:`62ae84e0`,at:[`charlotte-christian:beliefs.note.text`]},{t:`آية شعار العام 2026–27 هي Philippians 4:4-7.`,of:`2f879cf3`,at:[`charlotte-christian:beliefs.note.muted`]},{t:`«نؤمن بأن الله كائن واحد – غير محدود في عدله وحكمته وصلاحه ومحبته وقداسته، وكائن منذ الأزل وإلى الأبد في ثلاثة أقانيم: الآب والابن والروح القدس. وهو الخالق ذو السلطان على الكون، وبعنايته يحفظ ويسود كل ما صنعه».`,of:`353df0da`,at:[`charlotte-christian:beliefs.articles[0]`]},{t:`«نؤمن بأن يسوع المسيح، ابن الله، إله كامل وإنسان كامل، وأنه يخلّص شعبه من خطيتهم بحياته وموته وقيامته، وأنه الآن يملك على كنيسته وعلى العالم بكلمته وروحه».`,of:`6b2bb59b`,at:[`charlotte-christian:beliefs.articles[1]`]},{t:`«نؤمن بأن الروح القدس يجدّد الخطاة، ويسكن في المؤمنين، ويمكّنهم من أن يحيوا حياة التقوى وأن يستخدموا المواهب الروحية التي أعطاهم إياها».`,of:`98e462e3`,at:[`charlotte-christian:beliefs.articles[2]`]},{t:`«نؤمن بأن أسفار العهدين القديم والجديد هي كلمة الله الموحى بها، المعصومة والخالية من الخطأ، وهي سلطتنا النهائية في أمور العقيدة والممارسة».`,of:`bf248a55`,at:[`charlotte-christian:beliefs.articles[3]`]},{t:`«نؤمن بأن الخطاة يتبرّرون بالنعمة بالإيمان على أساس عمل المسيح المُكمَل (موته وقيامته)، ويحيون هذه الحياة بقوة الله».`,of:`78d0acc5`,at:[`charlotte-christian:beliefs.articles[4]`]},{t:`«نؤمن بأن الله يدعو أناسًا من الجنس البشري كله ليؤمنوا بابنه يسوع المسيح، وليصيروا أعضاء في جسده، أي الكنيسة. والذين يؤمنون بيسوع ربًّا ومخلّصًا ينعمون ببركات الله وبالشركة بعضهم مع بعض في جماعات الإيمان إلى أن يعود يسوع».`,of:`6246805c`,at:[`charlotte-christian:beliefs.articles[5]`]},{t:`«نؤمن بأن الإنسان، ذكرًا وأنثى، خُلق على صورة الله، لكنه سقط في الخطية بعصيان آدم وحواء. ونتيجةً للسقوط، يولد جميع الناس خطاة ومحتاجين إلى الخلاص».`,of:`d8bf7734`,at:[`charlotte-christian:beliefs.articles[6]`]},{t:`«نؤمن بأن الزواج علاقة عهد أنشأها الله لرجل وامرأة. والعلاقة الجنسية الحميمة عطية من الله، ومكانها الصحيح هو في إطار الزواج فقط».`,of:`e1e3a547`,at:[`charlotte-christian:beliefs.articles[7]`]},{t:`«نؤمن بأن يسوع المسيح، ابن الله، سيعود ليجدّد الخليقة كلها وليدين الأحياء والأموات».`,of:`fe82762c`,at:[`charlotte-christian:beliefs.articles[8]`]},{t:`«نؤمن بأن التعليم المسيحي شراكة بين الطلاب وهيئة التدريس وأولياء الأمور، تتيح للطلاب فرصة أن يتعلّموا ويختبروا المواد الأكاديمية والأنشطة المصاحبة للمنهج من خلال نظرة كتابية إلى العالم، في حضور هيئة تدريس تكرم المسيح».`,of:`2ed3e072`,at:[`charlotte-christian:beliefs.articles[9]`]},{t:`ما تقوله صفحات المدرسة العامة عن الإيمان عند التقديم وبعد التسجيل، وما تتركه دون ذكر.`,of:`2700b011`,at:[`charlotte-christian:families.headline`,`hickory-grove-christian:families.headline`]},{t:`عند التقديم`,of:`fbc4b036`,at:[`charlotte-christian:families.groups[0].name`,`hickory-grove-christian:families.groups[0].name`]},{t:`أسئلة عن إيمان الطالب`,of:`e7858d01`,at:[`charlotte-christian:families.groups[0].rows[0].label`]},{t:`يملأ المتقدّمون للصفوف 5–12 استبيانًا بخط اليد. يسأل عن «الأنشطة الروحية و/أو المرتبطة بالكنيسة» ويقول: «صِف علاقتك بيسوع المسيح».`,of:`13953c35`,at:[`charlotte-christian:families.groups[0].rows[0].detail`]},{t:`مقابلة الأسرة`,of:`94e34996`,at:[`charlotte-christian:families.groups[0].rows[1].label`,`hickory-grove-christian:families.groups[0].rows[1].label`]},{t:`تلتقي كل أسرة «أحد أعضاء فريق القيادة لدينا» من أجل «مشاركة الأهداف للخطوة التالية في رحلة طالبكم التعليمية».`,of:`47169ee7`,at:[`charlotte-christian:families.groups[0].rows[1].detail`]},{t:`إيمان وليّ الأمر نفسه`,of:`df592ad8`,at:[`charlotte-christian:families.groups[0].rows[2].label`,`hickory-grove-christian:families.groups[0].rows[4].label`]},{t:`لا تذكر الصفحات العامة ما إذا كان يجب أن يكون وليّ الأمر مسيحيًّا أو أن يرتاد كنيسة.`,of:`592818ab`,at:[`charlotte-christian:families.groups[0].rows[2].detail`]},{t:`توصية من راعي الكنيسة`,of:`cd83f059`,at:[`charlotte-christian:families.groups[0].rows[3].label`,`hickory-grove-christian:families.groups[0].rows[0].label`]},{t:`لا ترد أي توصية كهذه في خطوات التقديم أو قوائم التحقّق المنشورة.`,of:`34654847`,at:[`charlotte-christian:families.groups[0].rows[3].detail`]},{t:`التوقيع على بيان الإيمان`,of:`d7d8e80b`,at:[`charlotte-christian:families.groups[0].rows[4].label`]},{t:`غير وارد في خطوات التقديم المنشورة.`,of:`19d3e804`,at:[`charlotte-christian:families.groups[0].rows[4].detail`]},{t:`بعد التسجيل`,of:`d9033401`,at:[`charlotte-christian:families.groups[1].name`,`hickory-grove-christian:families.groups[1].name`]},{t:`Family Agreement Form`,of:`56281385`,at:[`charlotte-christian:families.groups[1].rows[0].label`]},{t:`«على أولياء الأمور والطلاب معًا أن يقرؤوا ويوقّعوا رقميًّا Back-to-School Form (نموذج العودة إلى المدرسة) على الإنترنت، ومنه Family Agreement Form (نموذج اتفاق الأسرة) وResponsible Use Policy (سياسة الاستخدام المسؤول)، في myCCS». والنموذج نفسه غير موجود في الموقع العام.`,of:`9cdbb748`,at:[`charlotte-christian:families.groups[1].rows[0].detail`]},{t:`مادة الكتاب المقدّس`,of:`6f74c399`,at:[`charlotte-christian:families.groups[1].rows[1].label`,`hickory-grove-christian:families.groups[1].rows[0].label`]},{t:`مطلوبة كل سنة، من Junior Kindergarten حتى الصف 12.`,of:`a97a83b2`,at:[`charlotte-christian:families.groups[1].rows[1].detail`]},{t:`الخلوات`,of:`6e3383f9`,at:[`charlotte-christian:families.groups[1].rows[2].label`]},{t:`في Middle School، «يشارك جميع الطلاب». وفي Upper School، «يُطلب من جميع الطلاب المشاركة».`,of:`914f06ef`,at:[`charlotte-christian:families.groups[1].rows[2].detail`]},{t:`سلوك الطالب`,of:`e448eab0`,at:[`charlotte-christian:families.groups[1].rows[3].label`]},{t:`ينتهي استبيان الصفوف 5–12 بعبارة: «أفهم أن عليّ الالتزام بهذه السياسات وأن أكرم المسيح في كل وقت». ويسري Honor Code (ميثاق الشرف) الخاص بالمدرسة على مدار الساعة، طوال السنة.`,of:`270396a5`,at:[`charlotte-christian:families.groups[1].rows[3].detail`]},{t:`الشراكة مع أولياء الأمور`,of:`253a65fc`,at:[`charlotte-christian:families.groups[1].rows[4].label`]},{t:`يصف بيان الإيمان التعليم المسيحي بأنه «شراكة بين الطلاب وهيئة التدريس وأولياء الأمور».`,of:`42b2acae`,at:[`charlotte-christian:families.groups[1].rows[4].detail`]},{t:`حضور الاجتماع الروحي`,of:`bf92e599`,at:[`charlotte-christian:families.groups[1].rows[5].label`,`hickory-grove-christian:families.groups[1].rows[3].label`]},{t:`لا تذكر الصفحات العامة ما إذا كان الاجتماع الروحي مطلوبًا.`,of:`889f792d`,at:[`charlotte-christian:families.groups[1].rows[5].detail`,`hickory-grove-christian:families.groups[1].rows[3].detail`]},{t:`يجب أن يشارك المعلّمون والموظفون الإيمان نفسه.`,of:`84aea924`,at:[`charlotte-christian:families.note.strong`,`hickory-grove-christian:families.note.strong`]},{t:`«يجب أن يكون جميع المتقدّمين للعمل مستعدين لخدمة المسيح في أدائهم اليومي لواجباتهم ولتأييد بيان إيماننا تأييدًا كاملًا».`,of:`b779f756`,at:[`charlotte-christian:families.note.text`]},{t:`تحتفظ المدرسة بـFamily Handbook (دليل الأسرة) وHonor Code وطلب التقديم الإلكتروني خلف تسجيل دخول خاص بالأسر، لا في موقعها العام.`,of:`122d7c31`,at:[`charlotte-christian:families.note.muted`]},{t:`تعدّ المدرسة الخدمة جزءًا من الإيمان. يخدم الطلاب منظمات غير ربحية محلية طوال السنة، ويمكن لطلاب Upper School الانضمام إلى رحلات إرسالية خلال Winterim (الفترة الشتوية).`,of:`e01e46c3`,at:[`charlotte-christian:service.headline`]},{t:`يوم خدمة للمدرسة كلها`,of:`233e085e`,at:[`charlotte-christian:service.entries[0].title`]},{t:`في ربيع 2026 قامت المدرسة بما يلي: «عبّأت 79,056 وجبة» مع Servants with a Heart.`,of:`06b1ea3b`,at:[`charlotte-christian:service.entries[0].text`]},{t:`Operation Christmas Child`,of:`c21f19dc`,at:[`charlotte-christian:service.entries[1].title`]},{t:`كان هدف خريف 2026 «تعبئة 1,850 علبة أحذية» قبل موعد الاجتماع الروحي لعيد الشكر. والشركاء الآخرون المذكورون بالاسم هم The Odd Sock وBright Blessings وRoof Above وHarvest Center.`,of:`83d1f787`,at:[`charlotte-christian:service.entries[1].text`]},{t:`Kingdom Impact Day`,of:`e47ad8fe`,at:[`charlotte-christian:service.entries[2].title`]},{t:`«تحدثت ست منظمات غير ربحية محلية عن رسالاتها» مع طلاب Middle School في ربيع 2026. وجمعت حملة منفصلة لأقلام التلوين في Middle School «98,484 قلم تلوين».`,of:`c375240b`,at:[`charlotte-christian:service.entries[2].text`]},{t:`الرحلات الإرسالية في Winterim`,of:`a2547bb4`,at:[`charlotte-christian:service.entries[3].title`]},{t:`«تقدّم Upper School فرصًا متنوعة لرحلات إرسالية محلية وإقليمية ودولية على مدار السنة، ومنها خلال Winterim». وتشمل قائمة 2027 أسبوع Serve Charlotte ورحلات مع SCORE International وRancho El Camino وSamaritan’s Feet.`,of:`583ae11a`,at:[`charlotte-christian:service.entries[3].text`]},{t:`ساعات الخدمة تبدأ في الصف السادس.`,of:`e7835585`,at:[`charlotte-christian:service.note.strong`]},{t:`«ابتداءً من الصف السادس، يُشجَّع الطلاب على إنجاز ساعات خدمة كل سنة».`,of:`b080f66b`,at:[`charlotte-christian:service.note.text`]},{t:`لا تذكر صفحات المدرسة عددًا للساعات لكل صف.`,of:`47443ecb`,at:[`charlotte-christian:service.note.muted`]},{t:`لكل قسم مدير/ة للحياة الروحية خاص به. وتذكر المدرسة أيضًا راعيًا للحرم المدرسي ومنسّق/ة للخدمة ومنسّق/ة للعبادة.`,of:`ce5f769a`,at:[`charlotte-christian:staff.headline`]},{t:`مدير/ة الحياة الروحية في Lower School`,of:`164a935d`,at:[`charlotte-christian:staff.people[0].role`]},{t:`مدير/ة الحياة الروحية في Middle School، معلّم/ة الكتاب المقدّس في Middle School`,of:`6e6cbd6a`,at:[`charlotte-christian:staff.people[1].role`]},{t:`مدير/ة الحياة الروحية في Upper School`,of:`0c132c42`,at:[`charlotte-christian:staff.people[2].role`]},{t:`راعي الحرم المدرسي`,of:`a4b30e91`,at:[`charlotte-christian:staff.people[3].role`]},{t:`معلّم/ة البثّ والأفلام في Upper School، منسّق/ة الخدمة`,of:`c6474b3e`,at:[`charlotte-christian:staff.people[4].role`]},{t:`منسّق/ة الفنون الجميلة والعبادة`,of:`d987057b`,at:[`charlotte-christian:staff.people[5].role`]},{t:`معلّم/ة الكتاب المقدّس في Upper School، رئيس/ة قسم الكتاب المقدّس`,of:`27b58135`,at:[`charlotte-christian:staff.people[6].role`]},{t:`ابدأ بمدير/ة الحياة الروحية في قسم طفلك.`,of:`b6411b3b`,at:[`charlotte-christian:staff.note.strong`]},{t:`خمسة معلّمين آخرين للكتاب المقدّس مذكورون في دليل موظفي المدرسة.`,of:`645d41b5`,at:[`charlotte-christian:staff.note.muted`]},{t:`دراسات في الكتاب المقدّس ومجموعات صلاة ورسائل بريد إلكتروني أسبوعية تنظّمها المدرسة لأولياء الأمور والأجداد.`,of:`af457c9d`,at:[`charlotte-christian:parents.headline`]},{t:`رسائل بريد إلكتروني إلى البيت`,of:`5601fdb3`,at:[`charlotte-christian:parents.entries[0].title`]},{t:`Chapel Recap من مديري الحياة الروحية، ورسالة كل يوم اثنين من مدير/ة المدرسة «فيها تأمّل روحي قصير وبعض طلبات الصلاة التي تخصّ المدرسة كلها».`,of:`188b61b8`,at:[`charlotte-christian:parents.entries[0].text`]},{t:`دراسة الكتاب المقدّس للسيدات Haverim`,of:`aed144bd`,at:[`charlotte-christian:parents.entries[1].title`]},{t:`«الأربعاء من 12:15-2:15 بعد الظهر أو الثلاثاء عبر Zoom من 7:30-8:30 مساءً». مفتوحة أمام «الأمهات والجدّات وأمهات الخرّيجين وأعضاء الكادر». ودراسة 2026–27 هي رسالة رومية.`,of:`5a3d57c7`,at:[`charlotte-christian:parents.entries[1].text`]},{t:`Parents in Prayer`,of:`ca4f5668`,at:[`charlotte-christian:parents.entries[2].title`]},{t:`أيام الخميس، 8:00–9:30 صباحًا في الحرم المدرسي، مع جلسة عبر الإنترنت نحو مرة في الشهر. «يصلّي أولياء الأمور المصلّون بانتظام من أجل البنين أو البنات في صف طفلهم».`,of:`839ff8ec`,at:[`charlotte-christian:parents.entries[2].text`]},{t:`Men’s Power Hour`,of:`68cdfc78`,at:[`charlotte-christian:parents.entries[3].title`]},{t:`«لرجال CCS»، لقاء صباحي شهري خارج الحرم المدرسي.`,of:`1a6be535`,at:[`charlotte-christian:parents.entries[3].text`]},{t:`Books and Fellowship`,of:`0bed32bd`,at:[`charlotte-christian:parents.entries[4].title`]},{t:`«لسيدات CCS»، مرة كل شهر من 8-9:15 صباحًا في منزل خاص.`,of:`65856cef`,at:[`charlotte-christian:parents.entries[4].text`]},{t:`Romans 12 Gatherings`,of:`a94dd44c`,at:[`charlotte-christian:parents.entries[5].title`]},{t:`مفتوحة أمام مجتمع المدرسة كله، للحديث عن «التنوع والانتماء ووصية يسوع بأن نعيش في وحدة ومصالحة بعضنا مع بعض».`,of:`28908133`,at:[`charlotte-christian:parents.entries[5].text`]},{t:`Knight to Knight`,of:`7ef8970a`,at:[`charlotte-christian:parents.entries[6].title`]},{t:`تُقرَن أسر طلاب Lower School وMiddle School بدفعة السنة الأخيرة من أجل «تشجيع» طلابها «والصلاة من أجلهم ومباركتهم» في سنتهم الأخيرة.`,of:`32740259`,at:[`charlotte-christian:parents.entries[6].text`]},{t:`كل وليّ أمر عضو في Parent Teacher Fellowship (رابطة أولياء الأمور والمعلّمين).`,of:`1eb6ea9d`,at:[`charlotte-christian:parents.note.strong`]},{t:`من مهامّها «دعم حيوي بالصلاة لكل جوانب مجتمع المدرسة».`,of:`dfbbcd1a`,at:[`charlotte-christian:parents.note.text`]},{t:`عشرة أسئلة تأخذها معك في الجولة. كلٌّ منها يتناول أمرًا تتركه صفحات المدرسة العامة بلا جواب أو تذكره بصيغتين.`,of:`d45f86d9`,at:[`charlotte-christian:ask.headline`]},{t:`هل يلزم أن يكون وليّ الأمر مسيحيًّا، أو منتميًا إلى كنيسة، ليُقبل الطفل؟`,of:`a0e1e94d`,at:[`charlotte-christian:ask.questions[0]`,`hickory-grove-christian:ask.questions[0]`]},{t:`ما الذي يطلب Family Agreement Form من أولياء الأمور والطلاب الموافقة عليه؟ وهل يمكننا قراءته قبل التقديم؟`,of:`f2ef1a03`,at:[`charlotte-christian:ask.questions[1]`]},{t:`ما الذي تبحثون عنه في إجابة الطالب عن «صِف علاقتك بيسوع المسيح»؟`,of:`e6939ed5`,at:[`charlotte-christian:ask.questions[2]`]},{t:`هل الاجتماع الروحي مطلوب من كل طالب؟`,of:`7ff625fb`,at:[`charlotte-christian:ask.questions[3]`,`hickory-grove-christian:ask.questions[3]`]},{t:`كم ساعة خدمة يحتاج كل صف؟ تقول إحدى الصفحات إن الساعات «يُشجَّع» عليها، وتذكر صفحة أخرى «ساعات الخدمة التي تطلبها المدرسة».`,of:`ac2ba319`,at:[`charlotte-christian:ask.questions[4]`]},{t:`متى تجتمع دراسات الكتاب المقدّس في Upper School، ومن يقودها، وكيف ينضم الطالب إلى إحداها؟`,of:`1d7fb7f2`,at:[`charlotte-christian:ask.questions[5]`]},{t:`أي منهج للكتاب المقدّس تستخدمه Lower School وMiddle School؟ وهل يوجد حفظ لآيات من الكتاب المقدّس؟`,of:`5c351240`,at:[`charlotte-christian:ask.questions[6]`]},{t:`ما الذي يفعله راعي الحرم المدرسي، وهل يمكن للأسر أن تلتقي به؟`,of:`6a615ab5`,at:[`charlotte-christian:ask.questions[7]`]},{t:`كيف يندمج هنا طالب جديد على الإيمان المسيحي، أو من ديانة أخرى؟`,of:`95f84c62`,at:[`charlotte-christian:ask.questions[8]`]},{t:`هل يمكننا قراءة Honor Code وFamily Handbook قبل التسجيل؟`,of:`9858f9f0`,at:[`charlotte-christian:ask.questions[9]`]},{t:`26 نوفمبر 2026`,of:`2ffc88e3`,at:[`charlotte-christian:ask.asOf`,`hickory-grove-christian:ask.asOf`]},{t:`مدرسة Hickory Grove Christian School هي «إحدى خدمات Hickory Grove Baptist Church». وقد أسّستها الكنيسة في عام 1995. يدرس الطلاب الكتاب المقدّس مادةً أساسية كل سنة، ويعلّم رعاة الكنيسة في الاجتماع الروحي.`,of:`4b2d51ae`,at:[`hickory-grove-christian:lead.strong`]},{t:`تقول المدرسة: «الإيمان المسيحي هو أساس كل ما نفعله في Hickory Grove Christian School».`,of:`9c24d508`,at:[`hickory-grove-christian:lead.muted`]},{t:`اجتماعات روحية في السنة`,of:`ae6fed75`,at:[`hickory-grove-christian:stats[0].label`]},{t:`ثمانية صباحات باجتماعات مقسّمة على المراحل، واجتماعان روحيان للمدرسة كلها، بحسب تقويم 2026–27`,of:`1d154f58`,at:[`hickory-grove-christian:stats[0].note`]},{t:`سنة من دراسة الكتاب المقدّس مادةً أساسية`,of:`4e53c4e2`,at:[`hickory-grove-christian:stats[1].label`]},{t:`«من Kindergarten حتى الصف 12»`,of:`d492bfb3`,at:[`hickory-grove-christian:stats[1].note`]},{t:`أرصدة في الكتاب المقدّس للتخرّج`,of:`0462af41`,at:[`hickory-grove-christian:stats[2].label`]},{t:`مادة واحدة في الكتاب المقدّس عن كل سنة من المرحلة الثانوية، من أصل 27 رصيدًا إجمالًا`,of:`eb9a213b`,at:[`hickory-grove-christian:stats[2].note`]},{t:`آية من الكتاب المقدّس يحفظها الطلاب`,of:`977db8d7`,at:[`hickory-grove-christian:stats[3].label`]},{t:`بنهاية المرحلة الابتدائية، بمعدّل آية واحدة تقريبًا كل أسبوع`,of:`a9d6d4a3`,at:[`hickory-grove-christian:stats[3].note`]},{t:`يُعقد الاجتماع الروحي عشر مرات في السنة، غالبًا صباح يوم الخميس. يتعبّد طلاب المرحلة الابتدائية أولًا، ثم طلاب المرحلتين المتوسطة والثانوية. ويعلّم فيه رعاة من Hickory Grove Baptist Church، ويساعد الطلاب في قيادة الترانيم.`,of:`aeef5967`,at:[`hickory-grove-christian:chapel.headline`]},{t:`الاجتماع الروحي للمرحلة الابتدائية`,of:`ae9892da`,at:[`hickory-grove-christian:chapel.entries[0].title`]},{t:`في الساعة 8:00 صباحًا في أيام الاجتماع الروحي. سلسلة 2026–27 «تتتبّع رجالًا ونساءً من الكتاب المقدّس وقفوا وقفة ثابتة من أجل الله».`,of:`cdc1a198`,at:[`hickory-grove-christian:chapel.entries[0].text`]},{t:`من المتحدثين في خريف 2026 رعاة التلمذة الأسرية في الكنيسة (Family Discipleship Pastors).`,of:`f070b25c`,at:[`hickory-grove-christian:chapel.entries[0].muted`]},{t:`الاجتماع الروحي للمرحلتين المتوسطة والثانوية`,of:`21c42430`,at:[`hickory-grove-christian:chapel.entries[1].title`]},{t:`في الساعة 9:30 صباحًا، في قاعة العبادة. موضوع 2026–27 هو «Here I Stand» (هنا أقف). يدوّن طلاب المرحلة المتوسطة ملاحظاتهم على أوراق الاجتماع الروحي، ويكتب طلاب المرحلة الثانوية في دفتر يوميات Here I Stand.`,of:`2b4cb461`,at:[`hickory-grove-christian:chapel.entries[1].text`]},{t:`من المتحدثين في خريف 2026 رعاة التلمذة الطلابية في الكنيسة (Student Discipleship Pastors). ويرتدي طلاب الصفوف 6–12 Honor Dress (الزيّ الرسمي) في الاجتماع الروحي.`,of:`2037a310`,at:[`hickory-grove-christian:chapel.entries[1].muted`]},{t:`يجمع اجتماع روحي لعيد الشكر وآخر لعيد الميلاد المدرسة كلها. ويقود طلاب الفنون الأدائية الاجتماع الروحي لعيد الميلاد.`,of:`7eb173c0`,at:[`hickory-grove-christian:chapel.entries[2].text`]},{t:`ولطلاب السنة الأخيرة أيضًا اجتماع روحي لتكريمهم (Senior Recognition Chapel) في أبريل.`,of:`77e07003`,at:[`hickory-grove-christian:chapel.entries[2].muted`]},{t:`التأمّلات الروحية في المرحلة الثانوية`,of:`0261e804`,at:[`hickory-grove-christian:chapel.entries[3].title`]},{t:`كل أربعاء، يستمع طلاب المرحلة الثانوية إلى تأمّل روحي عن واحد من «أربعة وثلاثين شاهدًا ثبتوا من أجل المسيح عبر عشرين قرنًا». ويروي معلّم أو راعٍ كل قصة.`,of:`0d1d343a`,at:[`hickory-grove-christian:chapel.entries[3].text`]},{t:`التأمّلات الروحية في المرحلة المتوسطة`,of:`342f0c8f`,at:[`hickory-grove-christian:chapel.entries[4].title`]},{t:`يقود المعلّمون تأمّلًا روحيًّا كل صباح. وقبل بدء الدوام، يفتح Quiet Time Cafe أبوابه للتأمّلات الروحية والكتابة في دفاتر اليوميات، من 7:00 إلى 7:15 صباحًا.`,of:`c1ee8239`,at:[`hickory-grove-christian:chapel.entries[4].text`]},{t:`Chapel Band`,of:`bbdc6ef1`,at:[`hickory-grove-christian:chapel.entries[5].title`]},{t:`طلاب المرحلة الثانوية «يخضعون لتجربة أداء، ويتدرّبون، ويساعدون رعاة العبادة لدينا في قيادة الاجتماع الروحي الذي يقوده الطلاب».`,of:`581f599a`,at:[`hickory-grove-christian:chapel.entries[5].text`]},{t:`Praise Team`,of:`cf0bf302`,at:[`hickory-grove-christian:chapel.entries[6].title`]},{t:`مقرّر في المرحلة المتوسطة «مصمَّم للطلاب الذين يرغبون في استخدام مواهبهم الموسيقية لقيادة الآخرين في العبادة».`,of:`6c6a0331`,at:[`hickory-grove-christian:chapel.entries[6].text`]},{t:`يمكن للأسر المشاهدة أو الحضور.`,of:`6bd62980`,at:[`hickory-grove-christian:chapel.note.strong`]},{t:`«يُبثّ كل اجتماع روحي مباشرةً ويُحفَظ في أرشيفنا». ويمكن للزوار في سن 18 فما فوق التسجيل مسبقًا.`,of:`ed0a2feb`,at:[`hickory-grove-christian:chapel.note.text`]},{t:`تتبع مواعيد الاجتماعات الروحية وأوقاتها تقويم المدرسة لعام 2026–27 ونموذج التسجيل الخاص بالاجتماع الروحي.`,of:`4d3d5f47`,at:[`hickory-grove-christian:chapel.note.muted`]},{t:`الكتاب المقدّس مادة أساسية مطلوبة كل سنة. إليك ما يدرسه كل صف، والأرصدة الأربعة في الكتاب المقدّس التي يحتاجها طالب المرحلة الثانوية للتخرّج.`,of:`7dc817f2`,at:[`hickory-grove-christian:classes.headline`]},{t:`«مواد الكتاب المقدّس إلزامية في المراحل الابتدائية والمتوسطة والثانوية».`,of:`03c8622c`,at:[`hickory-grove-christian:classes.intro.text`]},{t:`طلاب المرحلة الابتدائية «يحفظون نحو آية واحدة من الكتاب المقدّس كل أسبوع».`,of:`7d00f8bb`,at:[`hickory-grove-christian:classes.intro.muted`]},{t:`Elementary School`,of:`444c2b2d`,at:[`hickory-grove-christian:classes.groups[0].name`]},{t:`الكتاب المقدّس كل يوم`,of:`9d765c6c`,at:[`hickory-grove-christian:classes.groups[0].tally`]},{t:`من Kindergarten حتى الصف 5`,of:`edc71672`,at:[`hickory-grove-christian:classes.groups[0].rows[0].label`]},{t:`Building on the Rock (البناء على الصخر)، وهو «منهج في النظرة الكتابية إلى العالم ونظرة عامة على الكتاب المقدّس». «يبدأ كل يوم بالكتاب المقدّس، وتأمّل روحي يقدّمه المعلّم، وصلاة».`,of:`0008928c`,at:[`hickory-grove-christian:classes.groups[0].rows[0].detail`]},{t:`Kingdom Builders`,of:`9a94434e`,at:[`hickory-grove-christian:classes.groups[0].rows[1].label`]},{t:`حصة خاصة فيها «دروس مبنية على الكتاب المقدّس عن أمور مثل التواصل، وحلّ النزاعات، وحلّ المشكلات، والروح الرياضية».`,of:`34246ae1`,at:[`hickory-grove-christian:classes.groups[0].rows[1].detail`]},{t:`مادة في الكتاب المقدّس كل سنة`,of:`3ba77ed2`,at:[`hickory-grove-christian:classes.groups[1].tally`]},{t:`Building on the Rock`,of:`82cdd00e`,at:[`hickory-grove-christian:classes.groups[1].rows[0].label`]},{t:`النظرة المسيحية إلى العالم، من Summit Ministries.`,of:`61361a88`,at:[`hickory-grove-christian:classes.groups[1].rows[0].detail`]},{t:`Walking in Truth`,of:`2e76621e`,at:[`hickory-grove-christian:classes.groups[1].rows[1].label`]},{t:`يقارن المعتقدات الأساسية للمسيحية بالإسلام والمذهب الطبيعي والروحانية الجديدة. من Summit Ministries.`,of:`c3bd391f`,at:[`hickory-grove-christian:classes.groups[1].rows[1].detail`]},{t:`Light Bearers`,of:`77453ec1`,at:[`hickory-grove-christian:classes.groups[1].rows[2].label`]},{t:`يساعد الطلاب على «فهم كيف يمكنهم أن يعيشوا نظرتهم المسيحية إلى العالم في ثقافة ما بعد مسيحية». من Summit Ministries.`,of:`56bce3dc`,at:[`hickory-grove-christian:classes.groups[1].rows[2].detail`]},{t:`مقرّرات اختيارية في الإيمان والقيادة`,of:`427a5e5d`,at:[`hickory-grove-christian:classes.groups[1].rows[3].label`]},{t:`من المقرّرات Becoming a Young Man of God وBecoming a Young Woman of God (الصفان 7–8)، وStudent on Mission، وChristian Leadership لطلاب مختارين من الصف 8.`,of:`120cc5ee`,at:[`hickory-grove-christian:classes.groups[1].rows[3].detail`]},{t:`High School`,of:`8ab05d33`,at:[`hickory-grove-christian:classes.groups[2].name`]},{t:`4 أرصدة في الكتاب المقدّس للتخرّج`,of:`f3ba47fd`,at:[`hickory-grove-christian:classes.groups[2].tally`]},{t:`بمستوى الإعداد للجامعة أو Honors. يقوم الطلاب «بنظرة عامة على الكتاب المقدّس كله من خلال موضوعات كبرى».`,of:`f8d1174b`,at:[`hickory-grove-christian:classes.groups[2].rows[0].detail`]},{t:`بمستوى الإعداد للجامعة أو Honors. أسفار العهد الجديد، وعالمه، وحياة المسيح.`,of:`b2b63ff9`,at:[`hickory-grove-christian:classes.groups[2].rows[1].detail`]},{t:`Christian Apologetics`,of:`8e467286`,at:[`hickory-grove-christian:classes.groups[2].rows[2].label`]},{t:`بمستوى الإعداد للجامعة أو Honors. يتعلّم الطلاب «الأدلة المنطقية والفلسفية والتاريخية والعلمية على الإيمان المسيحي». والخيار الآخر هو Honors Introduction to Philosophy.`,of:`13dd27c3`,at:[`hickory-grove-christian:classes.groups[2].rows[2].detail`]},{t:`Systematic Theology`,of:`2723738e`,at:[`hickory-grove-christian:classes.groups[2].rows[3].label`]},{t:`بمستوى الإعداد للجامعة أو Honors. يعمل الطلاب على «ترسيخ فهمهم للعقائد الجوهرية في الإيمان المسيحي القويم». والخيار الآخر هو Honors Introduction to Ethics.`,of:`e795a1ff`,at:[`hickory-grove-christian:classes.groups[2].rows[3].detail`]},{t:`Introduction to Bible`,of:`167dd6e0`,at:[`hickory-grove-christian:classes.groups[2].rows[4].label`]},{t:`مقرّر «يُوصى به للطلاب الذين لم يلتحقوا قط بمدرسة مسيحية أو الجدد في HGCS». ويكون التسجيل فيه بتوصية من المدرسة.`,of:`5fc47c09`,at:[`hickory-grove-christian:classes.groups[2].rows[4].detail`]},{t:`مستوى Honors وأرصدة جامعية.`,of:`85df5dd5`,at:[`hickory-grove-christian:classes.note.strong`]},{t:`خمسة مقرّرات في الكتاب المقدّس بمستوى Honors هي مقرّرات تسجيل مزدوج عن طريق Judson College، وهي «برنامج المرحلة الجامعية الأولى في Southeastern Baptist Theological Seminary (SEBTS)».`,of:`aa231f5b`,at:[`hickory-grove-christian:classes.note.text`]},{t:`يدرس طلاب الانغماس في اللغة الإسبانية (Spanish Immersion) في المرحلة المتوسطة الكتاب المقدّس بالإسبانية.`,of:`d66b9c75`,at:[`hickory-grove-christian:classes.note.muted`]},{t:`حيث يتحدث الطلاب عن الإيمان في مجموعات أصغر: مجموعات شهرية في المرحلة المتوسطة، ومجموعات يقودها المعلّمون في المرحلة الثانوية.`,of:`ea4ea9d7`,at:[`hickory-grove-christian:groups.headline`]},{t:`Grove Groups`,of:`d6c20d68`,at:[`hickory-grove-christian:groups.entries[0].title`]},{t:`«في أول خميس من كل شهر»، يجتمع الطلاب حسب الصف ليتعلّموا من «حياة الشهداء والمرسَلين والمرشدين»، ثم ينقسمون إلى مجموعات تلمذة صغيرة.`,of:`8194ca24`,at:[`hickory-grove-christian:groups.entries[0].text`]},{t:`مجموعات التلمذة (D-groups)`,of:`5887b986`,at:[`hickory-grove-christian:groups.entries[1].title`]},{t:`«يُوضع كل طالب في المرحلة الثانوية في مجموعة تلمذة صغيرة يقودها معلّم». وتجتمع المجموعات في وقت Club Flex في منتصف اليوم في معظم أيام الخميس.`,of:`98ff950b`,at:[`hickory-grove-christian:groups.entries[1].text`]},{t:`راعٍ للطلاب في الحرم المدرسي`,of:`e2c19d02`,at:[`hickory-grove-christian:groups.entries[2].title`]},{t:`«راعي التلمذة الطلابية» في الكنيسة «موجود في الحرم المدرسي ومتاح لمحادثات فردية مع الطلاب».`,of:`ec0c5403`,at:[`hickory-grove-christian:groups.entries[2].text`]},{t:`Christian Leadership`,of:`7dddde73`,at:[`hickory-grove-christian:groups.entries[3].title`]},{t:`مقرّر لطلاب مختارين من الصف 8، «يُتوقَّع منهم أن يلتزموا بالخدمة قادةً في الحرم المدرسي طوال السنة الدراسية كلها».`,of:`439d6477`,at:[`hickory-grove-christian:groups.entries[3].text`]},{t:`والفرق الرياضية أيضًا.`,of:`4f01fc7b`,at:[`hickory-grove-christian:groups.note.strong`]},{t:`من أهداف برنامج الرياضة «تلمذة الرياضيين»: «سنسعى إلى تلمذة عظيمة داخل فرقنا».`,of:`ef4fa25a`,at:[`hickory-grove-christian:groups.note.text`]},{t:`رسالة المدرسة ورؤيتها، والمعتقدات التي تذكرها، والنتائج التي تأملها لكل طالب، بكلمات المدرسة نفسها.`,of:`e021d1dc`,at:[`hickory-grove-christian:beliefs.headline`]},{t:`«تتلمذ Hickory Grove Christian School الطلاب من خلال نظرة كتابية إلى العالم، فتكوّنهم في الدراسة الأكاديمية والرياضة والفنون ليكونوا ملتزمين بالله، ومرتبطين بالرسالة، وحكماء في المسيح، لكي يعرفوه ويُعرّفوا به».`,of:`5f8ff62b`,at:[`hickory-grove-christian:beliefs.mission`]},{t:`كل حق هو حق الله، ويجب أن تُدرَّس كل مادة دراسية من خلال نظرة كتابية إلى العالم.`,of:`36d2ef5b`,at:[`hickory-grove-christian:beliefs.tenets[0]`]},{t:`التعليم المسيحي جهد مشترك بين المدرسة والبيت وHickory Grove Baptist Church وجسد المسيح الأوسع.`,of:`f6f84166`,at:[`hickory-grove-christian:beliefs.tenets[1]`]},{t:`يجب أن يكون للتعليم المسيحي منظور أبدي، يركّز على خلاص الجيل القادم وتلمذته.`,of:`8c70a21c`,at:[`hickory-grove-christian:beliefs.tenets[2]`]},{t:`لا يُقاس النجاح في HGCS بقيادة الطلاب وتميّزهم ونزاهتهم فحسب، بل قبل كل شيء بالتزام بيسوع المسيح يدوم مدى الحياة.`,of:`0daba68d`,at:[`hickory-grove-christian:beliefs.tenets[3]`]},{t:`البيئة العالية المتطلّبات في الدراسة الأكاديمية والرياضة والفنون تُعِدّ الطلاب إعدادًا كاملًا للتحديات التي تنتظرهم.`,of:`65c91b53`,at:[`hickory-grove-christian:beliefs.tenets[4]`]},{t:`يتعلّم الطلاب بطرق مختلفة، لذلك يستخدم معلّمونا مجموعة متنوعة من استراتيجيات التدريس لدعم كل متعلّم.`,of:`afda4e27`,at:[`hickory-grove-christian:beliefs.tenets[5]`]},{t:`كل طالب مخلوق على صورة الله، وله احتياجات روحية وأكاديمية وجسدية وعقلية وعاطفية فريدة.`,of:`3e390e3c`,at:[`hickory-grove-christian:beliefs.tenets[6]`]},{t:`ملتزمون بالله`,of:`38f9009c`,at:[`hickory-grove-christian:beliefs.outcomes[0].name`]},{t:`مكرَّسون للرب بمحبّات مرتّبة ترتيبًا صحيحًا`,of:`6a42cc80`,at:[`hickory-grove-christian:beliefs.outcomes[0].text`]},{t:`مرتبطون بالرسالة`,of:`86faef7c`,at:[`hickory-grove-christian:beliefs.outcomes[1].name`]},{t:`منضمّون إلى جسد المسيح في رسالة مشتركة`,of:`5d2fac4e`,at:[`hickory-grove-christian:beliefs.outcomes[1].text`]},{t:`حكماء في المسيح`,of:`5686ade5`,at:[`hickory-grove-christian:beliefs.outcomes[2].name`]},{t:`يميّزون بين حكمة الله الكتابية وحكمة العالم`,of:`0148d0ab`,at:[`hickory-grove-christian:beliefs.outcomes[2].text`]},{t:`إحدى خدمات Hickory Grove Baptist Church.`,of:`675ad5ae`,at:[`hickory-grove-christian:beliefs.note.strong`]},{t:`رؤيتها: «أن نعرف المسيح ونُعرّف به من خلال التعليم المسيحي».`,of:`20f3e7c2`,at:[`hickory-grove-christian:beliefs.note.text`]},{t:`آية المدرسة هي Matthew 6:33. والمدرسة حاصلة على اعتماد مزدوج من Cognia ومن Association of Christian Schools International (ACSI).`,of:`1145ea45`,at:[`hickory-grove-christian:beliefs.note.muted`]},{t:`تتضمّن قائمة التحقّق لكل صف «Personal Recommendation form» (نموذج توصية شخصية) من راعي كنيسة الأسرة. وفي المرحلتين المتوسطة والثانوية تكون التوصية «من راعي كنيسة الطالب/الأسرة».`,of:`3492170f`,at:[`hickory-grove-christian:families.groups[0].rows[0].detail`]},{t:`«مقابلة الأسرة فرصة لمشاركة الرسالة والرؤية وبيان الإيمان، ولتقييم ما إذا كانت HGCS المكان المناسب لأسرتكم».`,of:`7e1fcf3b`,at:[`hickory-grove-christian:families.groups[0].rows[1].detail`]},{t:`استبيان الطالب`,of:`70bc4595`,at:[`hickory-grove-christian:families.groups[0].rows[2].label`]},{t:`يملأ المتقدّمون للصفوف 4–12 Student Questionnaire (استبيان الطالب). وأسئلته غير منشورة في الموقع العام.`,of:`58072980`,at:[`hickory-grove-christian:families.groups[0].rows[2].detail`]},{t:`أعضاء الكنيسة يقدّمون أولًا`,of:`62834a83`,at:[`hickory-grove-christian:families.groups[0].rows[3].label`]},{t:`فُتح باب التقديم في 2 نوفمبر 2026 لأعضاء الكنيسة وطلاب Early Education Center (مركز التعليم المبكر) والإخوة والأخوات، وفي 16 نوفمبر لجميع الأسر الجديدة.`,of:`ff1eefee`,at:[`hickory-grove-christian:families.groups[0].rows[3].detail`]},{t:`لا تذكر الصفحات العامة ما إذا كان يجب أن يكون وليّ الأمر مسيحيًّا أو منتميًا إلى كنيسة. لكن نموذج إبداء الاهتمام الخاص بمرحلة ما قبل المدرسة في Mallard Creek يسأل عن كنيسة الأسرة وإيمان الوالدين.`,of:`90bc5e19`,at:[`hickory-grove-christian:families.groups[0].rows[4].detail`]},{t:`الموافقة على بيان إيمان`,of:`4d0e62a1`,at:[`hickory-grove-christian:families.groups[0].rows[5].label`]},{t:`لا تذكر الصفحات العامة ما إذا كانت الأسر توقّع عليه.`,of:`78c021b6`,at:[`hickory-grove-christian:families.groups[0].rows[5].detail`]},{t:`مطلوبة كل سنة.`,of:`b2052a02`,at:[`hickory-grove-christian:families.groups[1].rows[0].detail`]},{t:`Honor Code`,of:`44cd5ffc`,at:[`hickory-grove-christian:families.groups[1].rows[1].label`]},{t:`«يوقّع كل طالب في المرحلة الثانوية على Student Honor Code (ميثاق شرف الطالب)، وهو عهد منظَّم حول النتائج الثلاث المتوقَّعة من طلابنا».`,of:`32678a3d`,at:[`hickory-grove-christian:families.groups[1].rows[1].detail`]},{t:`لباس الاجتماع الروحي`,of:`2f4b2596`,at:[`hickory-grove-christian:families.groups[1].rows[2].label`]},{t:`«Honor Dress مطلوب في جميع برامج الاجتماع الروحي في الصفوف 6-12 وفي بعض المناسبات الخاصة».`,of:`94b46255`,at:[`hickory-grove-christian:families.groups[1].rows[2].detail`]},{t:`يطلب إعلان الوظيفة «مسيحيًّا ملتزمًا يتّفق مع بيان إيمان المدرسة» و«ناشطًا في كنيسة محلية تؤمن بالكتاب المقدّس».`,of:`13cc08e6`,at:[`hickory-grove-christian:families.note.text`]},{t:`تحتفظ المدرسة بـParent-Student Handbook (دليل وليّ الأمر والطالب) وبطلب التقديم الإلكتروني خلف تسجيل دخول خاص بالأسر.`,of:`80ae7348`,at:[`hickory-grove-christian:families.note.muted`]},{t:`يذهب طلاب السنة الأخيرة كل سنة في رحلة إرسالية إلى جمهورية الدومينيكان، وتتبرّع المدرسة كلها لقضية ما كل ربع سنة.`,of:`c319faa6`,at:[`hickory-grove-christian:service.headline`]},{t:`الرحلة الإرسالية لطلاب السنة الأخيرة`,of:`33553cb2`,at:[`hickory-grove-christian:service.entries[0].title`]},{t:`«يخدم طلاب السنة الأخيرة لدينا معًا كل سنة في رحلة إرسالية إلى جمهورية الدومينيكان». ورحلة 2026–27 في يناير 2027.`,of:`e89f1c2f`,at:[`hickory-grove-christian:service.entries[0].text`]},{t:`أسبوع الإرسالية في المرحلة الثانوية`,of:`2ac49c4f`,at:[`hickory-grove-christian:service.entries[1].title`]},{t:`«بينما يكون طلاب السنة الأخيرة في الرحلة، يخدم باقي طلاب المرحلة الثانوية المجتمع المحلي من خلال أسبوع الإرسالية».`,of:`e298e406`,at:[`hickory-grove-christian:service.entries[1].text`]},{t:`جمع التبرّعات الإرسالية كل ربع سنة`,of:`d7df1e39`,at:[`hickory-grove-christian:service.entries[2].title`]},{t:`«في كل ربع سنة، تتبرّع أسرتنا المدرسية لدعم خدمة أو قضية محلية». ومن القضايا المذكورة XChange، وهي خدمة تابعة للكنيسة لمساعدة المدمنين؛ وOperation Christmas Child؛ وBaby Bottle Drive (حملة زجاجات الرضّع) «دعمًا لقدسية الحياة البشرية».`,of:`421bf44c`,at:[`hickory-grove-christian:service.entries[2].text`]},{t:`HGBC Food Pantry`,of:`2e9ac33b`,at:[`hickory-grove-christian:service.entries[3].title`]},{t:`يقوم طلاب Spanish Immersion «بدور المترجمين الفوريين كل أسبوع بينما يشارك رعاتنا الإنجيل مع مجتمعنا». ومختبر الزراعة المائية السمكية (aquaponics) في المرحلة الثانوية «يزرع الطعام لـHG Food Pantry».`,of:`5db014a7`,at:[`hickory-grove-christian:service.entries[3].text`]},{t:`Student on Mission`,of:`23157b7b`,at:[`hickory-grove-christian:service.entries[4].title`]},{t:`مقرّر في المرحلة المتوسطة «يدرس ما يفعله الله حول العالم وكيف يمكن للطلاب أن يخدموا شارلوت».`,of:`84aa6016`,at:[`hickory-grove-christian:service.entries[4].text`]},{t:`Global Missions & Language Certificate`,of:`80313ab8`,at:[`hickory-grove-christian:service.entries[5].title`]},{t:`يحصل عليها الطلاب بإتمام ثلاث وحدات في لغة أجنبية، ومقرّرات في الكتاب المقدّس بمستوى Honors، و«رحلة إرسالية دولية واحدة على الأقل»، وتدريب عملي أو تدريب ميداني في العمل الإرسالي.`,of:`b39f9bee`,at:[`hickory-grove-christian:service.entries[5].text`]},{t:`يضيف دليل المقرّرات شرطًا آخر: «أن يكون عضوًا فاعلًا في كنيسة ذات إيمان مماثل، ويُثبَت ذلك بخطاب توصية إيجابي من راعٍ، ويُفضَّل أن يكون راعي الشباب الخاص بالطالب».`,of:`ec79c40a`,at:[`hickory-grove-christian:service.entries[5].muted`]},{t:`الأسر المضيفة`,of:`08de32bd`,at:[`hickory-grove-christian:service.entries[6].title`]},{t:`يمكن لأسر الكنيسة وأسر المدرسة استضافة طالب دولي. وتسمّي المدرسة ذلك «الإرسالية المعكوسة».`,of:`ff765539`,at:[`hickory-grove-christian:service.entries[6].text`]},{t:`عمل إرسالي خارج شارلوت.`,of:`ccf8f5b9`,at:[`hickory-grove-christian:service.note.strong`]},{t:`تذكر المدرسة «جهود العمل الإرسالي الدولي في جمهورية الدومينيكان والإكوادور وهايتي وكينيا».`,of:`69d038ac`,at:[`hickory-grove-christian:service.note.text`]},{t:`لا تذكر صفحات المدرسة أي متطلّب لساعات الخدمة.`,of:`5de87f7f`,at:[`hickory-grove-christian:service.note.muted`]},{t:`يعلّم رعاة من Hickory Grove Baptist Church في الاجتماع الروحي ويقودون الجلسات المخصّصة لأولياء الأمور. ولا تذكر المدرسة قسيسًا خاصًّا بها.`,of:`91c82d15`,at:[`hickory-grove-christian:staff.headline`]},{t:`الراعي الأول، Hickory Grove Baptist Church؛ عضو في المجلس الاستشاري`,of:`62f34cd6`,at:[`hickory-grove-christian:staff.people[0].role`]},{t:`راعي التلمذة الطلابية، Hickory Grove Baptist Church`,of:`29d78e88`,at:[`hickory-grove-christian:staff.people[1].role`,`hickory-grove-christian:staff.people[2].role`]},{t:`راعي التلمذة الأسرية، Hickory Grove Baptist Church`,of:`f6d67519`,at:[`hickory-grove-christian:staff.people[3].role`,`hickory-grove-christian:staff.people[4].role`]},{t:`رئيس/ة قسم الكتاب المقدّس، المرحلة الثانوية`,of:`a7f858b3`,at:[`hickory-grove-christian:staff.people[5].role`]},{t:`الكتاب المقدّس والتربية البدنية، المرحلة المتوسطة`,of:`21497841`,at:[`hickory-grove-christian:staff.people[6].role`]},{t:`يتشارك المعلّمون والقادة تقديم التأمّلات الروحية يوم الأربعاء.`,of:`c96e81fc`,at:[`hickory-grove-christian:staff.note.strong`]},{t:`من المتحدثين في خريف 2026 مدير/ة المدرسة ومدير/ة المرحلة الثانوية.`,of:`78ceaec7`,at:[`hickory-grove-christian:staff.note.muted`]},{t:`جلسة لأولياء الأمور في أيام الاجتماع الروحي، وملخّصات لكل اجتماع روحي وتأمّل روحي تُرسَل إلى البيت، ومجموعة صلاة شهرية.`,of:`f368223d`,at:[`hickory-grove-christian:parents.headline`]},{t:`Lions Connect`,of:`d035b4a2`,at:[`hickory-grove-christian:parents.entries[0].title`]},{t:`«يجتمع Lions Connect في أيام الاجتماع الروحي، بين الاجتماع الروحي للمرحلة الابتدائية والاجتماع الروحي للمرحلتين المتوسطة والثانوية، لكي تتعبّد مع طفلك وتبقى للاجتماعين كليهما». ويقوده رعاة الكنيسة، في الساعة 9:00 صباحًا.`,of:`237fa7e7`,at:[`hickory-grove-christian:parents.entries[0].text`]},{t:`كانت موضوعات خريف 2026 «Because I Told You So» (لأنني قلت لك ذلك) و«Hard Providences» (تدابير العناية الإلهية الصعبة).`,of:`30748e72`,at:[`hickory-grove-christian:parents.entries[0].muted`]},{t:`Chapel at Home`,of:`303afda6`,at:[`hickory-grove-christian:parents.entries[1].title`]},{t:`بعد كل اجتماع روحي، تتلقّى الأسر ملخّصًا فيه الرسالة وآياتها من الكتاب المقدّس و«بعض الأسئلة للنقاش مع طفلك». وهناك نسخة للمرحلة الابتدائية ونسخة للمرحلتين المتوسطة والثانوية.`,of:`119beb08`,at:[`hickory-grove-christian:parents.entries[1].text`]},{t:`ملخّصات التأمّلات الروحية`,of:`d198ee5d`,at:[`hickory-grove-christian:parents.entries[2].title`]},{t:`ملخّص من صفحة واحدة لكل تأمّل روحي يُقدَّم يوم الأربعاء في المرحلة الثانوية، «لكي تسأل طالبك عنه على العشاء أو في السيارة».`,of:`8b520ec0`,at:[`hickory-grove-christian:parents.entries[2].text`]},{t:`Lions in Prayer`,of:`0b8e5ea6`,at:[`hickory-grove-christian:parents.entries[3].title`]},{t:`«يجتمع أولياء الأمور مرة كل شهر للصلاة من أجل طلابنا وموظفينا ومدرستنا». وتُعقد اللقاءات في الساعة 8:00 صباحًا في أول يوم اثنين من الشهر.`,of:`beaefa22`,at:[`hickory-grove-christian:parents.entries[3].text`]},{t:`Parent Teacher Fellowship (رابطة أولياء الأمور والمعلّمين).`,of:`b1101883`,at:[`hickory-grove-christian:parents.note.strong`]},{t:`«نسمّي أنفسنا شركة (fellowship) لأننا مؤمنون متّحدون في دفع التعليم من أجل الملكوت قُدُمًا».`,of:`09ed8c22`,at:[`hickory-grove-christian:parents.note.text`]},{t:`للتواصل: Cynthia Sampson، cynthiasampson@hgchristian.org.`,of:`2bfea94f`,at:[`hickory-grove-christian:parents.note.muted`]},{t:`اثنا عشر سؤالًا تأخذها معك في الجولة. كلٌّ منها يتناول أمرًا تتركه صفحات المدرسة العامة بلا جواب أو تذكره بصيغتين.`,of:`44bce139`,at:[`hickory-grove-christian:ask.headline`]},{t:`ما الذي يسأل عنه نموذج التوصية من راعي الكنيسة؟ وماذا لو لم يكن لأسرتنا راعي كنيسة؟`,of:`b242ce9b`,at:[`hickory-grove-christian:ask.questions[1]`]},{t:`هل يمكننا قراءة بيان الإيمان الذي يُعرض في مقابلة الأسرة؟ وهل توقّع الأسر عليه؟`,of:`e9e95fd8`,at:[`hickory-grove-christian:ask.questions[2]`]},{t:`كم مرة يُعقد الاجتماع الروحي؟ تقول إحدى الصفحات مرة في الشهر، وفي تقويم 2026–27 اجتماعان في مارس.`,of:`bce6454c`,at:[`hickory-grove-christian:ask.questions[4]`]},{t:`كم مرة تجتمع مجموعات التلمذة في المرحلة الثانوية؟ تقول إحدى الصفحات عدة مرات في الشهر، وتقول أخرى معظم أيام الخميس.`,of:`b8ed44ef`,at:[`hickory-grove-christian:ask.questions[5]`]},{t:`هل يذهب كل طلاب السنة الأخيرة في الرحلة الإرسالية إلى جمهورية الدومينيكان، وهل هي مشمولة في الرسوم الدراسية؟`,of:`895c399b`,at:[`hickory-grove-christian:ask.questions[6]`]},{t:`كم رصيدًا في الكتاب المقدّس يحتاج الطالب الذي يلتحق في الصف 10 أو 11 أو 12؟`,of:`a7b381c8`,at:[`hickory-grove-christian:ask.questions[7]`]},{t:`هل توجد أي خلوات، لأي صف؟`,of:`6423bdb4`,at:[`hickory-grove-christian:ask.questions[8]`]},{t:`هل ساعات الخدمة مطلوبة؟`,of:`65648d57`,at:[`hickory-grove-christian:ask.questions[9]`]},{t:`هل يوقّع طلاب المرحلتين الابتدائية والمتوسطة على Honor Code أيضًا؟`,of:`e43e6b9e`,at:[`hickory-grove-christian:ask.questions[10]`]},{t:`هل يمكننا قراءة Parent-Student Handbook قبل التسجيل؟`,of:`65b596cb`,at:[`hickory-grove-christian:ask.questions[11]`]}]};export{e as default};